def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    blocked = set()
    for p in observation.get("obstacles") or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            blocked.add((p[0], p[1]))

    def valid(dx, dy):
        nx, ny = sx + dx, sy + dy
        if gw and (nx < 0 or nx >= gw):
            return False
        if gh and (ny < 0 or ny >= gh):
            return False
        if (nx, ny) in blocked:
            return False
        return True

    def cand_to(target):
        tx, ty = target
        dx = 1 if tx > sx else -1 if tx < sx else 0
        dy = 1 if ty > sy else -1 if ty < sy else 0
        return [(dx, dy), (dx, 0), (0, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]

    def pick_target(items, prefer_chase=True):
        best = None
        bestv = None
        for it in items or []:
            x, y = pos(it, None)
            if x is None:
                continue
            ds = abs(x - sx) + abs(y - sy)
            do = abs(x - ox) + abs(y - oy)
            if prefer_chase:
                v = (ds - do, ds, do, x, y)
            else:
                v = (ds, do, x, y)
            if bestv is None or v < bestv:
                bestv = v
                best = (x, y)
        return best

    resources = observation.get("resources") or []
    target = pick_target(resources, True)

    if target is None:
        for key in ("control_points", "territory_targets", "targets", "points", "goals"):
            target = pick_target(observation.get(key) or [], True)
            if target is not None:
                break

    if target is None:
        # If no objective is visible, either pressure opponent or drift toward center.
        if (sx, sy) != (ox, oy):
            target = (ox, oy)
        else:
            target = (gw // 2 if gw else sx, gh // 2 if gh else sy)

    for dx, dy in cand_to(target):
        if valid(dx, dy):
            return [dx, dy]

    # Fallback: choose any legal move, preferring not to wait.
    for dx, dy in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)):
        if valid(dx, dy):
            return [dx, dy]

    return [0, 0]

